var callbackMapper = {
	map : function(fn) {
		if(typeof window.__FN_INDEX !== 'undefined' && window.__FN_INDEX !== null) {
			var proxyFnName = 'F' + window.__FN_INDEX;
			window.__PROXY_FN[proxyFnName] = fn;
		  	window.__FN_INDEX++;
			return proxyFnName;
		} else {
			throw new Error("Please initialise window.__FN_INDEX = 0 in index.js of your project.");
		}
	}
}

exports["getPermissionStatus'"] = function(err, success, permission) {
	return function() {
		var callback = callbackMapper.map(function(params) {
			success(params)();
		});
		JBridge.checkPermission(permission, callback);
	};
};

exports["requestPermission'"] = function(err, success, permissions) {
	return function() {
		var callback = callbackMapper.map(function(params) {
			success(JSON.stringify(params))();
		});
		JBridge.setPermissions(permissions, callback);
	};
};

const loopedFunction = function(){
    return loopedFunction
}
const getTracker = function(){
    var trackerJson = window.JOS && window.JOS.tracker || {};
    if (typeof trackerJson._trackException != "function"){
        trackerJson._trackException = loopedFunction;
    }
    if (typeof trackerJson._trackAction != "function"){
        trackerJson._trackAction = loopedFunction;
    }
    return trackerJson;
}
const tracker = getTracker();

exports._trackException = function(category){
    return function(subcategory){
            return function(label){
                return function(key){
                    return function(value) {
                        tracker._trackException(category)(subcategory)(label)(key)(value)();
                    }
                }
            }
    }
}

exports._trackApiCall = function(resp){
    tracker._trackAction("system")("debug")("api_response")(resp)();
}

exports.getValueFromLocalStoreImpl = function(key) {
  if (window.JOS && window.JOS.fetchAndDecrypt) {
    try {
      return window.JOS.fetchAndDecrypt(key);
    } catch (err) { }
  }
  return JBridge.getFromSharedPrefs(key);
};

exports.setValueToLocalStoreImpl = function(key, value) {
  if (window.JOS && window.JOS.encryptAndStore) {
    try {
      return window.JOS.encryptAndStore(key)(value);
    } catch (err) { }
  }
  return JBridge.setInSharedPrefs(key, value);
};

exports.deleteValueFromLocalStoreImpl = function(key) {
  if (window.JOS && window.JOS.deleteEncKeys) {
    try {
      window.JOS.deleteEncKeys(key);
    } catch (err) {
      JBridge.removeDataFromSharedPrefs(key);
    }
  } else {
    JBridge.removeDataFromSharedPrefs(key);
  }
};

module Presto.Core.Language.Runtime.API
  ( APIRunner
  , runAPIInteraction
  ) where

import Prelude

import Control.Monad.Except (throwError, runExcept)
import Control.Monad.Free (foldFree)
import Data.Either (Either(..))
import Effect.Aff (Aff)
import Effect.Exception (error)
import Foreign.Class (encode, decode)
import Presto.Core.Types.API (Request, Response) as API
import Presto.Core.Types.Language.Interaction (InteractionF(..), Interaction, ForeignIn(..), ForeignOut(..))

type APIRunner = API.Request -> Aff (API.Response String)

interpretAPI :: APIRunner -> InteractionF ~> Aff
interpretAPI apiRunner (Request (ForeignIn fgnIn) nextF) = do
  case runExcept $ decode fgnIn of
    -- This error should never happen if the `apiInteract` function is made right.
    Left err -> throwError (error ("apiInteract is broken: " <> show err))
    Right req -> do
      str <- apiRunner req
      pure $ nextF $ ForeignOut $ encode str


runAPIInteraction :: APIRunner -> Interaction ~> Aff
runAPIInteraction apiRunner = foldFree (interpretAPI apiRunner)
